[
  {
    "vulnerability": "SQL injection",
    "function": "do_login",
    "severity": "HIGH",
    "reason": "The user-supplied `user` and `pw` values are interpolated directly into an SQL query via an f-string, allowing an attacker to break out of the string literals and execute arbitrary SQL (e.g., `' OR '1'='1`)."
  },
  {
    "vulnerability": "Reflected Cross-Site Scripting (XSS)",
    "function": "do_reflect",
    "severity": "MEDIUM",
    "reason": "The `name` parameter from the query string is inserted into the HTML response without any HTML-encoding, allowing an attacker to inject arbitrary script that executes in the victim's browser."
  },
  {
    "vulnerability": "OS Command Injection",
    "function": "do_ping",
    "severity": "HIGH",
    "reason": "The `host` parameter is concatenated into a shell command string (`ping -c 1 {host}`) without sanitisation, so shell metacharacters (`;`, `|`, `&`, backticks, etc.) can be used to append or replace arbitrary commands."
  },
  {
    "vulnerability": "Information Disclosure",
    "function": "do_login",
    "severity": "MEDIUM",
    "reason": "On a SQL error the handler returns the raw database error message and the full constructed query string in the JSON response, leaking internal schema, table/column names, and implementation details to an unauthenticated attacker."
  },
  {
    "vulnerability": "Sensitive Data Exposure",
    "function": "do_login",
    "severity": "MEDIUM",
    "reason": "Upon successful authentication the handler returns the entire row including the `secret` column (e.g., admin session tokens) in the API response, exposing privileged data that should never leave the server."
  }
]
